import { randomBytes, randomInt, scryptSync, timingSafeEqual } from 'node:crypto';

/**
 * Pairing codes are generated by the gateway, shown once to the operator,
 * and stored only as a salted scrypt verifier. Never log a code.
 *
 * Generated codes use 12 Crockford base32 symbols (60 bits of entropy),
 * displayed as XXXX-XXXX-XXXX. Combined with scrypt this makes offline or
 * LAN guessing impractical; request rate limiting is added with the HTTP
 * server (Phase 4).
 */
const ALPHABET = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
const CODE_SYMBOLS = 12;
export const MIN_PAIRING_CODE_LENGTH = 10;

export interface ScryptParams {
  N: number;
  r: number;
  p: number;
}

/** ~16 MiB per verification; tuned for a laptop or Raspberry Pi gateway. */
export const DEFAULT_SCRYPT_PARAMS: ScryptParams = { N: 2 ** 14, r: 8, p: 1 };
const KEY_LENGTH = 32;
const SALT_LENGTH = 16;

export function generatePairingCode(): string {
  const symbols = Array.from({ length: CODE_SYMBOLS }, () => ALPHABET[randomInt(ALPHABET.length)] ?? '0');
  return [symbols.slice(0, 4), symbols.slice(4, 8), symbols.slice(8)].map((g) => g.join('')).join('-');
}

/** Case-, space- and hyphen-insensitive; Crockford look-alikes (O, I, L) are mapped. */
export function normalizePairingCode(input: string): string {
  return input
    .toUpperCase()
    .replace(/[\s-]/g, '')
    .replace(/O/g, '0')
    .replace(/[IL]/g, '1');
}

export class PairingCodeFormatError extends Error {
  override name = 'PairingCodeFormatError';
}

export function hashPairingCode(code: string, params: ScryptParams = DEFAULT_SCRYPT_PARAMS): string {
  const normalized = normalizePairingCode(code);
  if (normalized.length < MIN_PAIRING_CODE_LENGTH) {
    throw new PairingCodeFormatError(`Pairing codes must have at least ${MIN_PAIRING_CODE_LENGTH} characters`);
  }
  const salt = randomBytes(SALT_LENGTH);
  const hash = scryptSync(normalized, salt, KEY_LENGTH, { ...params, maxmem: 64 * 1024 * 1024 });
  return ['scrypt', params.N, params.r, params.p, salt.toString('base64url'), hash.toString('base64url')].join('$');
}

/** Constant-time verification against a stored verifier. Malformed verifiers never match. */
export function verifyPairingCode(code: string, verifier: string): boolean {
  const parts = verifier.split('$');
  if (parts.length !== 6 || parts[0] !== 'scrypt') {
    return false;
  }
  const [, nText, rText, pText, saltText, hashText] = parts;
  const N = Number(nText);
  const r = Number(rText);
  const p = Number(pText);
  if (![N, r, p].every((v) => Number.isInteger(v) && v > 0) || !saltText || !hashText) {
    return false;
  }
  const expected = Buffer.from(hashText, 'base64url');
  const actual = scryptSync(normalizePairingCode(code), Buffer.from(saltText, 'base64url'), expected.length, {
    N,
    r,
    p,
    maxmem: 64 * 1024 * 1024,
  });
  return expected.length === actual.length && timingSafeEqual(expected, actual);
}
